import match from "@/lib/sample-results/match.json";
import differentMaker from "@/lib/sample-results/different-maker.json";
import mismatch from "@/lib/sample-results/mismatch.json";
import { SAMPLE_RESULTS } from "@/lib/sample-results";
import { templateExplanation, type Explanation } from "@/lib/ai/guard";
import type { CheckResult } from "@/lib/check-service";

export type PhotoSample = { result: CheckResult; explanation: Explanation; recordedAt: string; photos: { label: string; pill: string } };
// JSON widens literal verdict/feature strings; these artifacts are generated by the typed sample builder.
const saved = { match, "different-maker": differentMaker, mismatch } as unknown as Record<string, PhotoSample | null>;
export const SAMPLES = SAMPLE_RESULTS.map(sample => {
  const photoSample = saved[sample.scenario.id];
  return { ...sample, result: photoSample?.result ?? sample.result, explanation: photoSample?.explanation ?? templateExplanation(sample.result), photos: photoSample?.photos ?? null, recordedAt: photoSample?.recordedAt ?? sample.result.checkedAt };
});
